#include <stdio.h>
#define MAX(a,b) ((a) > (b) ? (a) : (b))
#define ARRAY_LEN(a) (sizeof (a) / sizeof (a)[0])
int main(void) {
    int v[] = {3, 9, 4};
    printf("%d %zu\n", MAX(v[0], v[2]), ARRAY_LEN(v));
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
int main(int argc, char *argv[]) {
    if (argc != 3) { printf("usage: %s A B\n", argv[0]); return 1; }
    char *end;
    long a = strtol(argv[1], &end, 10);
    if (*end) { printf("bad number\n"); return 1; }
    long b = strtol(argv[2], &end, 10);
    if (*end) { printf("bad number\n"); return 1; }
    printf("%ld\n", a + b);
    return 0;
}

